import { McpServer } from "@modelcontextprotocol/server"
import { z } from "zod"

const server = new McpServer({ name: "orders", version: "1.0.0" })

server.registerTool(
  "get_order",
  {
    description: "Detaliile unei comenzi după id",
    inputSchema: z.object({ orderId: z.string() }),
  },
  async ({ orderId }) => ({
    content: [{ type: "text", text: await fetchOrder(orderId) }],
  }),
)
